    imc_shift_accumulator u_accumulator (
        .clk(clk),
        .rst_n(rst_n),
        .clear(acc_clear),
        .cmd_valid(acc_valid),
        .cmd_addr(acc_addr),
        .adc_code(acc_code),
        .shift_amount(acc_shift),
        .subtract(acc_subtract),
        .read_addr(acc_read_addr),
        .read_data(acc_data),
        .cmd_done(acc_done),
        .cmd_error(acc_error)
    );
    imc_fixed_scale u_scale (
        .value(acc_data),
        .shift(scale_shift),
        .scaled(scaled),
        .saturated(scale_saturated)
    );
    imc_round_divider u_divider (
        .clk(clk),
        .rst_n(rst_n),
        .clear(1'b0),
        .start(div_start),
        .numerator(div_numerator),
        .denominator(denominator_q),
        .ready(div_ready),
        .done(div_done),
        .error(div_error),
        .quotient(div_quotient),
        .remainder(unused_div_remainder)
    );
endmodule
`default_nettype wire
